VERSION = '2026-11-13.1'
PUBLIC_CONFIG = {'approved_for_publication': False,
 'privacy_version': '2026-11-13.1',
 'public_contact_email': 'admin@ptdtoday.com',
 'public_region': 'United States',
 'public_service_name': 'PTD Today | COSMOS',
 'terms_version': '2026-11-13.1'}
OLD_MOMENT = 'async function uploadFile(file){\n    const fd=new FormData();fd.append("file",file,file.name||"cosmos-media");return await api("/api/media/upload",{method:"POST",body:fd});\n  }'
NEW_MOMENT = 'async function uploadFile(file){\n    // COSMOS v9.5.5 rights declaration: shown for each new upload.\n    if(!window.confirm(RIGHTS_UPLOAD_MESSAGE))throw new Error(\'Upload cancelled. You must own or have permission to share this media.\');\n    const fd=new FormData();fd.append("file",file,file.name||"cosmos-media");\n    fd.set(\'rights_attested\',\'true\');fd.set(\'rights_version\',\'2026-11-13.1\');\n    return await api("/api/media/upload",{method:"POST",body:fd});\n  }'
RIGHTS_CONSTANT = "  const RIGHTS_UPLOAD_MESSAGE = 'I confirm that I created this media or have the required rights and permissions to upload it, including music, clips and consent from people shown. Unauthorized third-party videos and music are prohibited. Continue?';\n"
OLD_PROFILE = "const form=new FormData();form.append('file',file);\n      await api('/api/identity-media/'+universe+'/'+kind,{method:'POST',body:form});"
NEW_PROFILE = "if(!window.confirm(RIGHTS_UPLOAD_MESSAGE))throw new Error('Upload cancelled. You must own or have permission to share this image.');\n      const form=new FormData();form.append('file',file);\n      form.set('rights_attested','true');form.set('rights_version','2026-11-13.1');\n      await api('/api/identity-media/'+universe+'/'+kind,{method:'POST',body:form});"
OLD_MARKET = "async function uploadPhoto(listingId,file){\n const cleaned=await cleanImage(file);if(!cleaned)return;\n const form=new FormData();form.set('file',cleaned);\n await api('/api/market/listings/'+listingId+'/photo',{method:'POST',body:form});\n}"
NEW_MARKET = "async function uploadPhoto(listingId,file){\n if(!window.confirm('I confirm this image is my original work or I have permission to upload it. Unlicensed third-party images are prohibited.'))throw new Error('Photo upload cancelled.');\n const cleaned=await cleanImage(file);if(!cleaned)return;\n const form=new FormData();form.set('file',cleaned);\n form.set('rights_attested','true');form.set('rights_version','2026-11-13.1');\n await api('/api/market/listings/'+listingId+'/photo',{method:'POST',body:form});\n}"

def replacement(text,old,new,label):
    if new in text: return text
    if text.count(old)!=1: raise RuntimeError(f'Unexpected source for {label}: existing patch cannot safely apply. No changes made.')
    return text.replace(old,new,1)

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--mode',choices=('validate','apply'),required=True)
    args=ap.parse_args()
    root=pathlib.Path('.');cosmos=root/'cosmos-next.html';market=root/'cosmos-market-business.html';config=root/'cosmos-legal-config.json'
    if not cosmos.is_file() or not market.is_file():raise SystemExit('Missing COSMOS frontend or Marketplace file. No changes made.')
    source=cosmos.read_text(encoding='utf-8');mk=market.read_text(encoding='utf-8')
    try:
        changed=replacement(source,OLD_MOMENT,NEW_MOMENT,'moments/media upload')
        if RIGHTS_CONSTANT not in changed and NEW_MOMENT in changed:
            changed=changed.replace(NEW_MOMENT,RIGHTS_CONSTANT+NEW_MOMENT,1)
        changed=replacement(changed,OLD_PROFILE,NEW_PROFILE,'profile media')
        changed=changed.replace('2026-11-12.1',VERSION)
        newmk=replacement(mk,OLD_MARKET,NEW_MARKET,'marketplace photo')
        allowed={'operator_name','legal_email','mailing_address','dmca_email','approved_for_publication','public_service_name','public_contact_email','public_region','terms_version','privacy_version'}
        if config.exists():
            oldcfg=json.loads(config.read_text(encoding='utf-8'))
            if not isinstance(oldcfg,dict) or not set(oldcfg).issubset(allowed):
                raise RuntimeError('Legal config contains unexpected custom fields. Make a private backup and reconcile manually. No files changed.')
        pages={}
        for name,blob in PAGES.items():
            path=root/name
            data=zlib.decompress(base64.b85decode(blob)).decode('utf-8')
            if 'COSMOS_LEGAL_VERSION: '+VERSION not in data:raise RuntimeError('Legal version marker missing')
            if path.exists():
                older=path.read_text(encoding='utf-8')
                if older!=data and 'COSMOS_LEGAL_VERSION: ' not in older:
                    raise RuntimeError('Refusing to overwrite unrecognized '+name+'. No files changed.')
            pages[path]=data
        # This public file contains no private name/address. Historical GitHub commits are not erased.
        safe=json.dumps(PUBLIC_CONFIG,indent=2)+'\n'
        if args.mode=='validate':
            print('PASS: three brand-only policy pages, two upload UIs, frontend version sync and public-only config are patchable.')
            print('No files changed. Cloudflare backend attestation remains a separate deployment.')
            return
        cosmos.write_text(changed,encoding='utf-8');market.write_text(newmk,encoding='utf-8');config.write_text(safe,encoding='utf-8')
        for path,data in pages.items():path.write_text(data,encoding='utf-8')
        print('APPLIED: COSMOS v9.5.5 policy pages, public-only config, and media upload confirmations.')
        print('NOT activated: server-side rights enforcement or legal-acceptance enforcement; deploy the matching Life Worker after comparing production.')
    except (RuntimeError,ValueError,TypeError) as exc:
        raise SystemExit('ERROR: '+str(exc))
if __name__=='__main__':main()
